java.solution:
import java.util.*;

class Solution {
    static int firstFailing(boolean[] failed) {
        int low = 0, high = failed.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (failed[mid]) high = mid;
            else low = mid + 1;
        }
        return low < failed.length ? low : -1;
    }
}
